(function () {
  'use strict';
  var controller = null;

  const SEALS=[{"id": 1, "period": "Década de 1840", "desc": "El sello está formado por un círculo en el que se inserta la siguiente inscripción \"P. y. C\". Suele ir acompañado de un número en este caso el \"7\" que probablemente haga referencia al año de fabricación o al operario. Utilizado generalmente en piezas de vajilla y actualmente no se reproduce.", "image": "stamp-01.webp", "decade": 1840}, {"id": 2, "period": "Décadas 1840- 50", "desc": "Sello formado por una corona real y la leyenda \"PICKMAN Y Cª SEMI CHINA\", identificando la calidad de la pasta. El motivo de una corona fue utilizado por numerosas fábricas inglesas como la fábrica, G.M. & C.J. Mason de Staffordshire Potteries. (ha. 1830). GODDEN Geoffrey A. Enciclopedia of British Pottery porcelain Marks. London, 1988, pág. 418). El modelo está documentado sin fecha en el archivo de la fábrica (carpeta de patentes) y representado en piezas de colecciones privadas. Se aplicó en vajillas y piezas de tocador, y actualmente no se reproduce.", "image": "stamp-02.webp", "decade": 1840}, {"id": 3, "period": "Décadas 1840- 50", "desc": "Sello formado por una corona real y la inscripción \"PICKMAN & Cº / FABRIC REAL\". Es muy similar a los sellos nº 2 y 4, pero cambiándoles la leyenda. Se utilizó para piezas de vajilla y tocador. Modelo documentado sin fecha en el archivo de la fábrica (carpeta de patentes). Actualmente no se reproduce.", "image": "stamp-03.webp", "decade": 1840}, {"id": 4, "period": "Décadas 1840- 50", "desc": "Sello formado por una corona real y la inscripción \"PICKMAN Y Cº\". Es similar a los modelos Nº 2 y 3, para piezas de tocador. El modelo está documentado si fecha en el archivo de la fábrica (carpeta de patentes). Actualmente no se reproduce.", "image": "stamp-04.webp", "decade": 1840}, {"id": 5, "period": "Décadas 1840- 50", "desc": "El sello está formado por una corona rodeada de la inscripción \"PICKMAN Y Cª / SEMICHINA\". Solo se conoce por referencias bibliográficas. Probablemente se utilizó para piezas de vajilla y tocador. Actualmente no se reproduce.", "image": "stamp-05.webp", "decade": 1840}, {"id": 6, "period": "Décadas 1840- 50", "desc": "Sello formado por una corona real con la inscripción \"PICKMAN Y Cª SEMI CHINA\", inscrita en un registro. Actualmente no se conoce en piezas de vajillas. El modelo está documentado sin fecha en el archivo de la fábrica, (carpeta de patentes).", "image": "stamp-06.webp", "decade": 1840}, {"id": 7, "period": "Décadas 1840- 50", "desc": "El sello se compone de un óvalo con decoración de perlas y la inscripción \"PICKMAN Y Cª / CARTUJA / SEVILLA\". Se utilizó, para piezas de vajilla y tocador. El modelo figura representado si fecha en planchas grabadas de estampación y en piezas de colecciones privadas. Actualmente no se reproduce.", "image": "stamp-07.webp", "decade": 1840}, {"id": 8, "period": "Décadas 1840- 50", "desc": "El sello representa un óvalo con decoración de perlas y cruces, y lleva la inscripción \"PICKMAN Y Cª / CARTUJA / SEVILLA\" . No se conoce su reproducción en piezas de vajillas, pero el modelo está documentado sin fecha en el archivo de la fábrica (carpeta de patentes). También aparece representado en planchas de cobre para estampar. Actualmente no se reproduce.", "image": "stamp-08.webp", "decade": 1840}, {"id": 9, "period": "Décadas 1840- 50", "desc": "El sello está formado por un óvalo con decoración de perlas y rosetas. Lleva la inscripción \"P. Y C ª / CARTUJA\". El modelo está representado sin fecha en las planchas grabadas de estampación. Se utilizó para piezas de vajilla y tocador, y actualmente no se reproduce.", "image": "stamp-09.webp", "decade": 1840}, {"id": 10, "period": "Décadas 1840- 50", "desc": "Sello formado por un círculo con decoración de hojas y rosetas muy esquematizadas. En el interior figura la inscripción \"PICKMAN Y Cª / CARTUJA / SEVILLA\". El modelo está representado si fecha en planchas grabadas de estampación. Actualmente no se reproduce.", "image": "stamp-10.webp", "decade": 1840}, {"id": 11, "period": "Décadas 1840- 50", "desc": "El sello representa un círculo formado por ramilletes, figurando la inscripción \"Vistas / de / España / P y Cª\", para piezas decoradas con vistas de ciudades de España. Ésta serie, comenzó a realizarse desde la fundación hasta la década de 1870. El modelo está representado sin fecha en planchas grabadas. Estaría inspirado en un sello inglés, al parecer en la misma plancha aparece un modelo similar con la inscripción \" SCOTCH SPRING\".", "image": "stamp-11.webp", "decade": 1840}, {"id": 12, "period": "De 1841 a 1870", "desc": "Sello estampado que representa dos águilas sosteniendo un cartel \" VISTAS / DE / ESPAÑA / PICKMAN. Y COMP...\" De momento no se conoce ninguna pieza con este sello, aunque está reproducido en planchas de estampación de la fábrica grabadas con vistas de capitales europeas. Por lo tanto se deduce que se empleó para piezas de vistas urbanas de España y Europa. Ésta serie comenzó a realizarse desde su fundación hasta aproximadamente la década de 1870. Actualmente no se utiliza.", "image": "stamp-12.webp", "decade": 1840}, {"id": 13, "period": "Décadas 1840- 50", "desc": "El sello representa un león sobre una corona real con la inscripción \"N. 3/ CARTUJA\". Actualmente no se conoce su reproducción en piezas de vajillas. El sello está representado sin fecha en planchas de cobre para estampar. Posiblemente está inspirado en un modelo similar de la fábrica inglesa Goodwing & Harris de Staffordshire (GODDEN, Geoffrey A.: Encyclopaedia of British Pottery and Porcelain Marks. London, 1998, pág. 281).", "image": "stamp-13.webp", "decade": 1840}, {"id": 18, "period": "De 1841 a 1880", "desc": "Sello impreso en la pasta formado por un ancla y la inscripción \"PICKMAN Y Cª\". Éste modelo está documentado sin fecha en el archivo de la fábrica (carpeta de patentes) y en piezas de loza y azulejos. Presenta diversas medidas según la pieza. Se utilizó para vajillas y azulejos, actualmente no se produce.", "image": "stamp-18.webp", "decade": 1840}, {"id": 20, "period": "Décadas de 1840,1850 y 1860", "desc": "Sello estampado formado por un óvalo con la inscripción \"P y Cª\" en su interior. Rematado por una corona real, y en la parte inferior lleva motivos florales y filacteria con la leyenda \"Victoria\". Actualmente no se conoce su reproducción en piezas de loza, pero está documentado por referencias bibliográficas y figura en planchas de cobre para estampación. Es muy similar a un sello utilizado por la fábrica inglesa de John Ridway & Cº de Stafordshire Potterys 1830 - 55. (GODDEN Geoffrey A.: Encyclopaedya of British Pottery and Porcelain Marks. London, 1988, pág. 533.) Actualmente no se reproduce.", "image": "stamp-20.webp", "decade": 1840}, {"id": 25, "period": "De 1840 a 1850", "desc": "Sello estampado formado por el escudo de la corona real inglesa y la leyenda \"PICKMAN Y COMP. ÍA./ CARTUJA\". El motivo de armas reales fue muy utilizado en sellos de las industrias inglesas de loza durante todo el siglo XIX. El modelo está documentado sin fecha en el archivo (carpeta de patentes). Este sello se utilizó para piezas de vajilla y tocador, y actualmente no se reproduce.", "image": "stamp-25.webp", "decade": 1840}, {"id": 29, "period": "De 1841 a 1899", "desc": "El sello representa la leyenda \"PICKMANN Y Cª CHINA OPACA\" inscrita en un segmento de círculo. No se conoce ninguna pieza con este sello, sin embargo se documenta en referencias bibliográficas. Actualmente no se utiliza.", "image": "stamp-29.webp", "decade": 1840}, {"id": 14, "period": "Finales década 1850", "desc": "El sello representa seis medallas con los premios adjudicados a la fábrica de la Cartuja. Estas figuras enlazadas con roleos vegetales rodeando una cartela rectangular central, donde se lee la inscripción \"PICKMAN Y COMPAÑÍA / MANUFACTURA DE LA CARTUJA / SEVILLA\". Siguiendo el sentido de las agujas del reloj, aparecen escritos los galardones siguientes: 1. \"Medalla de primera clase. The Universal Society for the Incouregements Artisanal Industries London 1851. 1er. Class to the earthenware. Manufactory of Cartuja\". 2, \"Medalla de Oro. Exposición de Sevilla de 1858. (Escudo Real al Centro)\". 3.\" Premiada por la Sociedad Económica de Amigos del País. La ves siempre fiel. 1858. Sevilla. (al centro escudo de la Institución)\", 4.\"Ysabel II, Reyna de las Españas . 1857. ( Al centro busto regio a izdas.) Madrid\", 5. \"Medalla de 1ª Clase. Exposición Pública al Mérito en las Artes. Madrid. 1850.\"6, \"Medalla de Oro. Academie Nationale Agricole.Manufcaturiere et Comerciale. 1er Class. Medaille d H'onneur. Decoratión. M. Pickman. Sevilla.1857\".Este modelo está localizado en piezas de vajilla. Se conoce otra versión de este sello fechado en 1860 y siglado con el nª 15, donde aparece con una medalla más y diversa decoración de roleos vegetales. Actualmente no se reproduce.", "image": "stamp-14.webp", "decade": 1850}, {"id": 19, "period": "De 1850 a 1880", "desc": "El sello está formado por un registro con decoración de rocallas, rematado por una corona y la inscripción \"PICKMAN. Y. COMP.íA / CARTUJA\".Por el momento, no se conoce su reproducción en piezas de loza, pero está presentado sin fecha en planchas de cobre para estampación, donde aparece grabado junto a un decorado para vajillas similar al estampado modelo \"Fibra\". Actualmente no se utiliza.", "image": "stamp-19.webp", "decade": 1850}, {"id": 21, "period": "Décadas de 1850,1870y 1880", "desc": "Sello estampado formado por un cinturón de hebilla, símbolo de la orden de la Jarretera inglesa del S.XIV, figurando la leyenda en su interior \"PICKMAN Y C.ª / CHINA ORIENTAL / SEVILLA\". Se utilizó, para piezas de vajilla y tocador. El modelo está documentado sin fecha en el archivo de la fábrica (carpeta de patentes) y aparece representado en planchas de estampación y en piezas de loza. Actualmente no se reproduce.", "image": "stamp-21.webp", "decade": 1850}, {"id": 22, "period": "Décadas de 1850,1860,1870y 1880", "desc": "El sello representa un pergamino con la leyenda \"PICKMAN Y Cª / CHINA OPACA / SEVILLA\". El modelo aparece sin fecha en piezas de loza y en planchas de estampación. Se utilizó para piezas de vajilla y tocador, y actualmente no se reproduce.", "image": "stamp-22.webp", "decade": 1850}, {"id": 23, "period": "De 1850 a 1870", "desc": "El sello representa un águila sosteniendo con el pico una filacteria con la leyenda \"PICKMAN Y Cª / SEVILLA\". En la parte inferior lleva la inscripción \"CHINA VOLCÁNICA\", haciendo referencia a la calidad de la loza. Actualmente, no se conoce su reproducción en piezas de loza, pero está documentado sin fecha en el archivo de la fábrica (carpeta de patentes) y representado en planchas de estampación. Actualmente no se reproduce.", "image": "stamp-23.webp", "decade": 1850}, {"id": 24, "period": "De 1850 a 1870", "desc": "Sello estampado formado por un doble óvalo, rematado en un lazo y la leyenda \"PICKMAN Y Cª/ SEVILLA/ \"CHINA VOLCÁNICA\". No se conoce su reproducción en piezas de loza, pero está documentado sin fecha en la (carpeta de patentes) y representado en planchas de cobre para estampación. Actualmente no se reproduce.", "image": "stamp-24.webp", "decade": 1850}, {"id": 59, "period": "De 1850 a 1899", "desc": "El sello representa un óvalo con la inscripción \"PICKMAN Y Cº / CARTUJA / SEVILLA\". Se utilizó para marcar losetas fabricadas por Pickman y Cía, en el siglo XIX. El modelo está localizado en piezas conservadas en el Conjunto Monumental La Cartuja de Sevilla. Un modelo similar se empleo como sello administrativo en los comienzos de la fundación.", "image": "stamp-59.webp", "decade": 1850}, {"id": 60, "period": "De 1850 a 1899", "desc": "Sello impreso formado por la inscripción \"PICKMAN Y Cª / CARTUJA / SEVILLA\", acompañada de la cruz de malta. Este diseño se utilizó exclusivamente para marcar tejas planas. El mismo modelo se volvió a reproducir en el siglo XX variándose la inscripción de \" S.A.\" en el siglo XX, en lugar de \"Cº\", haciendo referencia al cambio de razón social de la empresa en 1899. En el Conjunto Monumental La Cartuja de Sevilla se conservan numerosas tejas selladas con esta inscripción. Actualmente la producción de tejas ha cesado.", "image": "stamp-60.webp", "decade": 1850}, {"id": 61, "period": "De 1850 a 1899", "desc": "Sello impreso formado por la inscripción \"PICKMAN Y Cª / CARTUJA / SEVILLA\". Se utilizó para tejas de construcción, fabricadaspor Pickman en el siglo XIX y principios del XX. En las tareas de rehabilitación del Conjunto Monumental La Cartuja de Sevilla se localizaron un gran número de tejas similares pertenecientes a los talleres fabriles. Actualmente no se producen.", "image": "stamp-61.webp", "decade": 1850}, {"id": 15, "period": "1862", "desc": "Sello similar al nº 14, representa siete medallas con los premios adjudicados a la fábrica de La Cartuja, enlazadas por roleos florales, rodeando una cartela rectangular central, donde se lee la inscripción \" PICKMAN Y COMPAÑÍA/ MANUFACTURA DE LA CARTUJA/ SEVILLA\". Siguiendo el sentido de las agujas del reloj, aparecen escritos los galardones siguientes: 1. Medalla de 1ª clase. The Universal Society for the Incouregements Artisanal Industries London, 1851. 1er. Class to the earthenware. Manufactory of Cartuja\". 2, \"Medalla de Oro. Exposición de Sevilla de 1858. (Escudo Real al Centro)\" 3. \"Medalla de Oro. Sociedad Económica de Amigos del País. Alicante. (Emblema de la entidad, al centro), ( h. 1860). 4. \" Premiada por la Sociedad Económica de Amigos del País. La ves siempre fiel. 1858. Sevilla. (Al centro escudo de la Institución)\". 5, Ysabel Segunda, Reyna de las Españas. 1857. (al centro, busto regio a izda.). Madrid, 1850\".6. \"Medalla de la 1ª Clase. Exposición Pública al Mérito en las Artes. Madrid, 1850\". 7, \" Medalla de Oro. Academie nationale Agricole. Manufacturiere et Comerciale. 1 er Class. Medaille d'honneur Décoratión. M. Pickman. Sevilla, 1857\". Éste modelo fue posiblemente el sello conmemorativo de la visita real de Isabel II a la fábrica el año 1862, al figurar en piezas de la vajilla, realizada con tal motivo y regaladas a la monarca. Actualmente se reproduce de forma similar, véase el sello Nº 55.", "image": "stamp-15.webp", "decade": 1860}, {"id": 16, "period": "De 1862 a 1880", "desc": "Sello estampado formado por un doble círculo y leyenda \"PICKMAN Y Cª / 1862/MEDALLA / EXPOSICIÓN DE / LONDRES / CHINA OPACA / SEVILLA\".Presenta diversidad de color y tamaño. El modelo está documentado sin fecha, en el archivo de la fábrica (carpeta de patentes) y representado en planchas de estampación y en piezas de loza. Es muy similar al modelo nº 17. Se utilizó para todo tipo de piezas de loza y en algunos casos para azulejos. Actualmente no se reproduce.", "image": "stamp-16.webp", "decade": 1860}, {"id": 17, "period": "De 1862 a 1880", "desc": "Sello estampado formado por un doble círculo y leyenda \"PICKMAN Y Cª / 1862/MEDALLA DE LONDRES / CHINA ORIENTAL / SEVILLA\". El modelo está representado en planchas de estampación de la fábrica y en azulejos de Pickman conservados en el conjunto monumental La Cartuja de Sevilla. Es muy similar al nº 16, se utilizó para todo tipo de piezas de loza y en algunos casos para azulejos. Actualmente no se reproduce.", "image": "stamp-17.webp", "decade": 1860}, {"id": 27, "period": "De 1860 a 1880", "desc": "El sello representa un cinturón con hebilla, símbolo de la Jarretera inglesa del XIV. En su interior, aparece un león rampante junto a un castillo y la leyenda \"PICKMAN Y Cª / CHINA OPACA / SEVILLA\". Presenta diversidad de color y medidas según la pieza. El modelo está representado sin fecha en piezas de loza y en el archivo de (carpeta de patentes). Se utilizó para todo tipo de piezas de lozas comunes, industriales y artísticas. Actualmente no se reproduce.", "image": "stamp-27.webp", "decade": 1860}, {"id": 64, "period": "De 1860 a 1899", "desc": "Sello impreso en la pasta. Sus elementos se recogen en tres registros. En la zona inferior se coloca la orden de la Jarretera con la numeración en su interior \"20\", referente a la medida del azulejo, en este caso de 2 cm, también puede aparecer en el Nº 15. Remarcando el ángulo se puede leer \"MEDALLA DE ORO\". En el registro central, dividido en dos franjas, se encuentra la inscripción \"PICKMAN Y Cª / LA CARTUJA DE SEVILLA\". En el registro superior, bajo la corona real, figura de nuevo el cinturón y hebilla en que se inscribe la leyenda \" REAL FÁBRICA\". Este sello se utilizó para los azulejos generalmente decorados con técnicas estampadas o \"cloisonné\" y en barro blanco. Un modelo similar, véase el Nº 69, se volvió a reproducir en el siglo XX. Solo se varió la inscripción de Cª por S.A., haciendo referencia al cambio de razón social de la industria en 1899. El modelo está localizado en numerosos azulejos conservados en el Conjunto Monumental La Cartuja de Sevilla. Actualmente no se utiliza, pues la fabricación de azulejos concluyó a finales de la década de 1920.", "image": "stamp-64.webp", "decade": 1860}, {"id": 26, "period": "Década 1870", "desc": "Sello estampado formado por el escudo de la corona real española con la inscripción \"REAL FÁBRICA DE LA CARTUJA DE / PICKMAN Y CÍA / SEVILLA\". El modelo está documentado por referencias bibliográficas y en el archivo de la fábrica, ( carpeta de patentes), donde aparece sin fecha. Se utilizó para series limitadas de piezas de vajilla y tocador encargadas por la Familia Real Española. Actualmente no se reproduce.", "image": "stamp-26.webp", "decade": 1870}, {"id": 28, "period": "De 1870 a 1899", "desc": "Sello estampado formado por un óvalo imitando ferronía y la inscripción \"PICKMAN Y C ª SEVILLA\". Presenta variedad de tamaño, según la pieza. El modelo está documentado en la carpeta de patentes y en las carpetas de pruebas de planchas de estampación, figurando desde el 1880 a1899. Este sello se utilizó para todo tipo de piezas. Actualmente no se reproduce.", "image": "stamp-28.webp", "decade": 1870}, {"id": 30, "period": "De 1878 a 1899", "desc": "Sello impreso formado por un doble círculo y leyenda \"PICKMAN Y Cª CHINA OPACA / (SEVLLA) GRAN/ MEDALLA / ORO / PARIS / 78\". Puede aparecer con variedad de medidas, según la pieza. El modelo está representado sin fecha en piezas de loza y en el archivo de la fábrica (carpeta de patentes). Se utilizó para vajillas, azulejos y cerámica artística. Actualmente no se reproduce.", "image": "stamp-30.webp", "decade": 1870}, {"id": 58, "period": "De 1870 a 1899", "desc": "Sello impreso, representa un ancla enlazada a una cuerda y a su vez inscrita en un doble círculo con la inscripción \"PICKMAN Y Cª/ SEVILLA\". Este sello está localizado en el departamento de serigrafía de la fábrica y representando en azulejos conservados en el Conjunto Monumental La Cartuja de Sevilla. Actualmente no se utiliza.", "image": "stamp-58.webp", "decade": 1870}, {"id": 62, "period": "De 1870 a 1899", "desc": "Sello impreso formado por un óvalo y en su interior la inscripción \"CARTUJA / PICKMAN Y Cª / SEVILLA\". Se utilizó generalmente para azulejos decorados con técnica de arista y en barro marga. Este modelo está representado en numerosos azulejos conservados en el Conjunto Monumental La Cartuja de Sevilla. Actualmente no se reproduce, pues la fabricación de azulejos concluyó a finales de la década de 1920.", "image": "stamp-62.webp", "decade": 1870}, {"id": 63, "period": "De 1870 a 1899", "desc": "El sello representa un óvalo con la inscripción \"PICKMAN Y Cª / LA CARTUJA DE / SEVILLA\". Se utilizó generalmente para azulejos con técnica de arista y en barro blanco o marga. El mismo sello se realizó posteriormente en el s. XX con la inscripción \" PICKMAN S.A. / CARTUJA DE SEVILLA\". El modelo está reproducido en numerosos azulejos, conservados en el Conjunto Monumental La Cartuja de Sevilla. Actualmente no se utiliza, pues la fabricación de azulejos concluyó a finales de la década de 1920.", "image": "stamp-63.webp", "decade": 1870}, {"id": 65, "period": "De 1870 a 1899", "desc": "Sello impreso en la pasta. Sus elementos se recogen en dos registros. En la zona inferior lleva la inscripción \"MEDALLA DE ORO / PICKMAN Y Cª / CARTUJA / SEVILLA / 10\". El número hace alusión a la medida del azulejo en este caso de 10 cm. En la zona superior aparece bajo la corona real el cinturón y la hebilla con el ancla y la inscripción \"REAL FÁBRICA\". Este sello se utilizó para azulejos generalmente decorados en técnicas estampadas o \"cloisonné\" y fabricados en loza de pedernal o barro blanco. Está localizado en azulejos conservados en el Conjunto Monumental de La Cartuja de Sevilla. Actualmente no se reproduce, pues la fabricación de azulejos concluyó a finales de la década de 1920.", "image": "stamp-65.webp", "decade": 1870}, {"id": 31, "period": "Entre 1880 y 1910", "desc": "El sello representa un círculo, figurando en su interior un ancla, un semicírculo y la inscripción \"PICKMAN * SEVILLA / CARTUJA\". El modelo puede presentarse impreso o estampado y con variedad de tamaño y color, según la pieza. Se conoce por referencias documentales del archivo de la fábrica, al parecer en las carpetas de planchas de prueba desde 1880. Posteriormente se patentó en 1892, según copia de carta dirigida al Ministro de Fomento, (A.F.C.S. Libro Copiador de Cartas Ad. 2,26 de octubre de 1892, pág: 48). Se utilizó para piezas de vajilla. Actualmente no se reproduce.", "image": "stamp-31.webp", "decade": 1880}, {"id": 38, "period": "De 1880 a 1899", "desc": "El sello representa un doble círculo y leyenda \"PICKMAN Y Cª / CHINA OPACA / *SEVILLA*\". Presenta variedad de tamaño y color, según la pieza. Éste modelo está documentado en la carpeta decorados Nº 3, donde aparece por primera vez junto a un dibujo realizado por los grabadores Maeso y López el 25 de Noviembre de 1896. Actualmente no se produce.", "image": "stamp-38.webp", "decade": 1880}, {"id": 39, "period": "De 1880 a 1899", "desc": "Sello compuesto por un doble círculo con leyenda \"PICKMAN Y Cª / *SEVILLA*\". Presenta variedad de tamaño y color sin fecha en el archivo de la fábrica (carpeta de patentes). Actualmente no se reproduce.", "image": "stamp-39.webp", "decade": 1880}, {"id": 32, "period": "1892", "desc": "El sello representa la Giralda de Sevilla, adornada con ramilletes y hojas de olivos y filacteria, inscrita en un círculo con decoración geométrica y la inscripción \"PICKMAN Y Cª/ SEVILLA\". Este modelo se presentó junto a varios diseños similares, según se reproducen en una carta de Ricardo Pickman dirigida a Pickman y Cía desde San Sebastián, el 24 de Septiembre de 1892. Posiblemente quedaría seleccionado el siglado con el nº 33, al patentarse solo éste ese mismo año. Por el momento no se conoce ninguna pieza con ese sello y actualmente no se reproduce.", "image": "stamp-32.webp", "decade": 1890}, {"id": 33, "period": "1892", "desc": "Sello estampado formado por la Giralda de Sevilla y la inscripción \"PICKMAN SEVILLA\", inscrita en un círculo. No se conoce ninguna pieza identificada con este modelo, aunque está documentado en la fábrica. Su patente se solicitó en1892, según carta dirigida al Ministro de Fomento, (A.F.C.S. Libro copiador de Cartas Ad.2, 15 de Noviembre de 1892, Pág. 49). Actualmente no se reproduce.", "image": "stamp-33.webp", "decade": 1890}, {"id": 34, "period": "1892", "desc": "El sello representa un águila con alas extendidas, rematando un doble círculo con las alas extendidas, rematando un doble círculo, rodeadas por roleos y ramas de laurel. En el interior lleva la leyenda \" PICKMAN & ROYAL CARTUJA WORKS/ SEVILLE\". No se conoce ninguna pieza con este sello aunque está documentado en la fábrica, solicitándose la patente en 1892, (A.C.F.S. Libro copiador de cartas Ad. 2, 26 de Julio de 1892, pág. 36). También se ha localizado en la carpeta de decorados Nº 2, figurando junto a un dibujo realizado por los grabadores Emilio y López, fechado el 12 de Mayo de 1892. Este modelo al aparecer con la leyenda en inglés, posiblemente fuera utilizado para piezas de importación a países de habla inglesa como Estados Unidos. Asimismo podría estar inspirado en un sello, utilizado por la fábrica \"Clementson Brothers\" (1870- 1910), Hanley, Inglaterra, (GODDEN, Geoffrey A.: Encyclopaedia of British Pottery and Porcelain Marks. London, 1988, pág. 150.) Actualmente no se reproduce.", "image": "stamp-34.webp", "decade": 1890}, {"id": 35, "period": "De 1892 a 1899", "desc": "Sello estampado similar al Nº 34, representado con un águila de alas extendidas, rematando un doble círculo con la leyenda \"PICKMAN & ROYAL STONE WARE/ +SEVILLE+\". En la parte inferior le acompaña una decoración de roleos y ramas de laurel. Actualmente no se conoce ninguna pieza con este sello, aunque está documentado sin fecha en la fábrica (carpeta de patentes). El modelo al parecer con la leyenda en inglés posiblemente fuera utilizado, al igual que el Nº 34, para las piezas de importación a países de habla inglesa como Estados Unidos. Actualmente no se reproduce.", "image": "stamp-35.webp", "decade": 1890}, {"id": 36, "period": "De 1892 a 1899", "desc": "Sello estampado compuesto por un doble círculo con la leyenda \"PICKMAN Y Cª / CHINA OPACA / MEDALLA ORO / *SEVILLA*\".Puede presentarse estampado o impreso y con variedad de tamaño y color, según la pieza. Se patentó al aparecer la solicitud en 1892 (A.F.C.S. Libro copiador de Cartas Ad. 2, el 4 de Agosto de 1892, pág. 44). Asimismo, está documentado en planchas de estampación y en la carpeta de decorados nº 3 a partir de 1896. Actualmente no se reproduce.", "image": "stamp-36.webp", "decade": 1890}, {"id": 37, "period": "De 1892 a 1899", "desc": "Sello estampado formado por un águila de alas extendidas, rematando un doble círculo con roleos y ramas de laurel y leyenda \"PICKMAN Cª / LA CARTUJA DE / SEVILLA\".El modelo está documentado en la carpeta decorados nº 2 figurando junto a un dibujo realizado por los grabadores Emilio y Viñas, el 5 Junio de 1893. Este sello similar a los números 34 y 35, puede aparecer con una leyenda, referente al nombre del decorado del estampado, como sería el caso del \"Roma\" o \"Vistas\". Se utilizó para piezas de vajillas, y actualmente no se reproduce.", "image": "stamp-37.webp", "decade": 1890}, {"id": 40, "period": "De 1899 a 1900", "desc": "Sello formado por un doble círculo y la leyenda \"PICKMAN / CHINA OPACA / MEDALLA / ORO / *SEVILLA*\". El sello presenta diversidad de color y medidas. Posiblemente fue utilizado en la transición del cambio de Pickman y Cía a Pickman S.A. en 1899, al no aparecer identificación de la razón social a la que pertenecía la industria. Es muy similar al modelo Nº 36 y 42 pero cambiándose parte de la inscripción. Se utilizó para todo tipo de vajillas y piezas artísticas.", "image": "stamp-40.webp", "decade": 1890}, {"id": 41, "period": "De 1899 a 1930", "desc": "Sello formado por un doble círculo con leyenda \"PICKMAN S.A. / CHINA / OPACA / *SEVILLA*\". El modelo presenta variedad de color y medidas, según la pieza. Está documentado en la carpeta de decorados nº 3, donde aparece por primera vez junto a un dibujo realizado por Manuel López y Manuel Machado, el 5 de septiembre de 1899. Es similar el Nº 38, variando parte de la leyenda. Actualmente no se utiliza.", "image": "stamp-41.webp", "decade": 1890}, {"id": 42, "period": "De 1899 a 1930", "desc": "Sello estampado formado por un doble círculo y la inscripción \"PICKMAN S.A. / CHINA / OPACA / MEDALLA / ORO / *SEVILLA*\". El modelo presenta diversidad de color y medidas, según la pieza. Es similar al Nº 36, modificándose la leyenda al cambiar la razón social de Pickman y Cía en Pickman S.A., en febrero de 1899. El sello está documentado en la carpeta de decorados nº 3 donde aparece por primera vez junto a un dibujo realizado por los grabadores Manuel Machado y Jiménez con fecha de 18 de septiembre de 1899. Actualmente no se utiliza.", "image": "stamp-42.webp", "decade": 1890}, {"id": 70, "period": "1899", "desc": "El sello representa una vista de la torre del Oro de Sevilla, una cartela y la leyenda \"PICKMAN / SOCIEDAD ANONIMA / FABRICA / DE / LOZA EN / LA CARTUJA DE SEVILLA\". El modelo se grabó por primera vez el 20 de Septiembre de 1899 por José de la Viña, figurando en la carpeta de decorados Nº 3. Actualmente no se utiliza.", "image": "stamp-70.webp", "decade": 1890}, {"id": 71, "period": "1899", "desc": "Sello estampado que representa una vista de la Giralda de Sevilla y la leyenda \"PICKMAN / SOCIEDAD / ANONIMA / FABRICA DE LOZA / EN / LA / CARTUJA DE SEVILLA\" inscrita en varias cartelas. El modelo se grabó por primera vez el 20 de Septiembre de 1899 por José de la Viña, figurando en la carpeta de decorados Nº 3. Actualmente no se utiliza.", "image": "stamp-71.webp", "decade": 1890}, {"id": 72, "period": "1899", "desc": "Sello estampado que representa una vista de la Puerta de Honor de La Cartuja y la leyenda \"PICKMAN / SOCIEDAD/ANONIMA / FABRICA DE LOZA / EN / LA CARTUJA DE SEVILLA\". El modelo se grabó por primera vez el 20 de Septiembre de 1899 por José de la Viña, figurando en la carpeta Nº 3 de decorados de planchas de estampación. Una iconografía similar aparece en facturas, en la contraportada del catálogo de azulejos de 1907 y en la tarifa de precios de 1959. Actualmente no se utiliza.", "image": "stamp-72.webp", "decade": 1890}, {"id": 43, "period": "De 1900 a 1905", "desc": "Sello estampado formado por un óvalo, imitando ferronía y la inscripción \"PICKMAN S.A. SEVILLA\". Presenta variedad de tamaño según la pieza. El modelo es similar al Nº 28 y está documentado en la carpeta de decorados nº 3 donde aparece por primera vez junto a un dibujo realizado por los grabadores Manuel Machado y Jiménez el 20 de Enero de 1900. Este sello se utilizó para piezas de vajilla. Actualmente no se reproduce.", "image": "stamp-43.webp", "decade": 1900}, {"id": 44, "period": "De 1900 a 1965", "desc": "El sello representa el ancla, inscrita en un doble círculo y la inscripción \"PICKMAN S.A. SEVILLA / CARTUJA\". Presenta diversidad de color y medidas, según la pieza y el decorado. Este sello puede aparecer acompañado de una inscripción, referente a la denominación del decorado de la pieza. EL modelo está documentado en la carpeta de decorados Nº 3, donde figura por primera vez junto a un dibujo, realizado por Manuel López y Manuel Machado el 11 de Octubre de 1900. Asimismo se reproduce en las tarifas de los años 1933 y 1956 y en el catálogo de artículos sanitarios del año 1937. Posteriormente, se renovó en 1952.", "image": "stamp-44.webp", "decade": 1900}, {"id": 45, "period": "De 1908 a 1930", "desc": "Sello formado por la inscripción \"PICKMAN SEVILLA\". El modelo está documentado en la carpeta de decorados de estampación Nº 5, donde aparece por primera vez junto a un dibujo, realizado por los grabadores Viña, López y Machado el 20 de febrero de 1908. Se utilizó para identificar piezas de vajillas. Actualmente no se reproduce.", "image": "stamp-45.webp", "decade": 1900}, {"id": 48, "period": "De 1900 a 1930", "desc": "Sello estampado formado por el ancla, inscrita en un semicírculo y a su vez en un círculo completo con la leyenda \"PICKMAN S.A. SEVILLA / CARTUJA\". El modelo es muy similar al Nº 44, diferenciándose en el ancla que presenta las extremidades muy curvas. Puede aparecer con diversidad de tamaño y color, según la pieza. Está documentado en la carpeta de decorados Nº 6, figurando por primera vez el 12 de octubre de 1927 junto a un dibujo, realizado por los grabadores José Fernández y Manuel López. Se utilizó para identificar piezas de vajillas y actualmente no se reproduce.", "image": "stamp-48.webp", "decade": 1900}, {"id": 66, "period": "Décadas de 1900,1910,1920, y 1930", "desc": "El sello representa la inscripción \"PICKMAN S.A. / SEVILLA\". El modelo está representado en ladrillos refractarios conservados en el Conjunto Monumental La Cartuja de Sevilla. Actualmente no se reproduce, pues la fabricación de piezas refractarias concluyó a finales de la década de 1920.", "image": "stamp-66.webp", "decade": 1900}, {"id": 67, "period": "Décadas de 1900,1910, y 1920", "desc": "Sello impreso similar al Nº 64, variándole la inscripción de Cía por S.A., haciendo referencia al cambio de razón social de la industria en 1899. Este modelo está representado en azulejos conservados en el Conjunto Monumental la Cartuja de Sevilla. Actualmente no se reproduce, pues la fabricación de azulejos concluyó a finales de la década de 1920.", "image": "stamp-67.webp", "decade": 1900}, {"id": 68, "period": "Décadas de 1900,1910 y 1920", "desc": "Sello impreso formado por la inscripción \"PICKMAN S.A./CARTUJA/SEVILLA\". Es muy similar al Nº 60, variándole la inscripción \"PICKMAN Y Cía\" por \"PICKMAN S.A.\", haciendo referencia al cambio de la razón social de la industria en 1899. El sello está representado en numerosas tejas, conservadas en el Conjunto Monumental La Cartuja de Sevilla. Se utilizó exclusivamente para marcar tejas, actualmente esta producción ha desaparecido.", "image": "stamp-68.webp", "decade": 1900}, {"id": 69, "period": "Décadas de 1900,1910,1920, y 1930", "desc": "Sello impreso formado por un óvalo y en su interior la inscripción \"PICKMAN Sd A.ª / CARTUJA / * DE* / SEVILLA\". En algunos casos esta leyenda puede aparecer con el artículo \"La\" juntoa a \" Cartuja\". Está representado en numerosos azulejos, conservados en el Conjunto Monumental La Cartuja de Sevilla. Se utilizó generalmente para azulejos elaborados con técnica de arista y en barro marga. Actualmente no se reproduce, pues la fabricación de azulejos concluyó a finales de la década de 1920.", "image": "stamp-69.webp", "decade": 1900}, {"id": 73, "period": "1909", "desc": "Sello estampado representa una iconografía de los hornos botella de la Cartuja y un jarrón artístico, elaborado en la fábrica, rematando la composición figura la inscripción \"PICKMAN S.A. / LA CARTUJA\". En la parte inferior se representa un cartel con la leyenda \"MADRID / 1907 / GRAN PREMIO / ZARAGOZA / 1908\". Asimismo, el modelo puede figurar acompañado de una inscripción publicitaria, en este caso.\"REPRESENTANTE EN CANARIAS S. PEREZ HIDALGO\". El diseño está documentado en la carpeta de decorados Nº 5, donde aparece realizado por el grabador José de la Viña, el 31 de mayo de 1909. Hoy se utiliza en la decoración de ceniceros con fines publicitarios.", "image": "stamp-73.webp", "decade": 1900}, {"id": 74, "period": "1909", "desc": "Sello estampado representa una iconografía de los hornos botella de la fábrica, un ánfora y una cartela en la que se lee la leyenda \"GRAN PREMIO/MADRID 1907 ZARAGOZA 1908\". La composición se completa con la inscripción \"PICKMAN S.A. LA CARTUJA\". El modelo está documentado en la carpeta decorados Nº 5, donde aparece realizado por el grabador José de la Viña el 31 de mayo de 1909. Hoy se utiliza como de decoración de ceniceros con fines publicitarios.", "image": "stamp-74.webp", "decade": 1900}, {"id": 46, "period": "De 1917 a 1930", "desc": "Sello estampado formado por el ancla y la leyenda \"LA CARTUJA/PICKMAN/SEVILLA\". El modelo generalmente aparece estampado en color negro y presenta diversidad de tamaño, según la pieza. Está documentado en la carpeta de decorados nº 6 donde figura por primera vez junto a un dibujo, realizado por Viña Rodríguez, el 4 de Agosto de 1917. Se utilizó para vajillas, placas de azulejos artísticos y sanitarios. Actualmente no se reproduce.", "image": "stamp-46.webp", "decade": 1910}, {"id": 47, "period": "De 1914 a 1930", "desc": "Sello similar al nº 47, representa el ancla y a leyenda \"LA CARTUJA / P.S.\". Este modelo generalmente aparece estampado en color negro y presenta diversidad de tamaño, según la pieza. En algunos casos se reproduce con la inscripción \"Corea\" en la parte inferior, alusiva al decorado de la pieza. Está representado sin fecha en planchas de estampación. Se utilizó para vajillas y actualmente no se reproduce.", "image": "stamp-47.webp", "decade": 1910}, {"id": 49, "period": "De 1932 a 1965", "desc": "El modelo representa un águila con las alas extendidas, rematando un doble círculo, rodeado de roleos y ramas de laurel. En su interior aparece la leyenda \"PICKMAN S.A. / LA/CARTUJA / DE / *SEVILLA*\". El sello es similar al Nº 37, variándole la leyenda de Cía, por S.A., referente al cambio de la razón social de la empresa en 1899. Asimismo puede aparecer con una leyenda o número en la base, identificando el decorado de la pieza, figurando en este caso \"Roma\". Está documentado en la carpeta de decorados Nº 7, donde aparece por primera vez junto a un dibujo, realizado por los grabadores López y Gargallo, el 12 de febrero de 1932. Presenta diversidad de color y medidas, según la pieza. Se utilizó para todo tipo de piezas de loza y sanitarios, actualmente no se reproduce.", "image": "stamp-49.webp", "decade": 1930}, {"id": 75, "period": "Décadas de 1930 y 1940", "desc": "El sello representa una vista de la puerta de Honor de La Cartuja inscrita en un doble círculo y acompañado de la leyenda \"PICKMAN S.A. FABRICA DE LOZA / PUERTA DE HONOR DE / LA CARTUJA / PINTADO A MANO\". En la parte inferior lleva el dibujo de un ancla, el modelo está localizado sin fecha en planchas de estampación. Es similar al sello Nº 71. Posiblemente se utilizó para series limitadas de piezas pintadas a mano, actualmente no se conoce su reproducción en piezas de loza.", "image": "stamp-75.webp", "decade": 1930}, {"id": 76, "period": "Décadas de 1930 y 1940", "desc": "Sello estampado representa un ancla flanqueada por dos rosetas y la leyenda \"FÁBRICA DE LOZA / LA CARTUJA\". Éste modelo está localizado sin fecha en las planchas de estampación. Posiblemente el sello se utilizó para series limitadas. Actualmente no se conoce su reproducción en piezas de loza.", "image": "stamp-76.webp", "decade": 1930}, {"id": 77, "period": "Décadas de 1930 y 1940", "desc": "Sello que representa un ancla inscrita en tres círculos concéntricos y la leyenda \"PICKMAN S.A. SEVILLA / CARTUJA\". Este modelo está localizados sin fecha en planchas de estampación. Posiblemente el sello se utilizó para series limitadas. Actualmente no se conoce su reproducción en piezas de loza.", "image": "stamp-77.webp", "decade": 1930}, {"id": 78, "period": "Décadas de 1930 y 1950", "desc": "Sello que representa un águila con las alas abiertas sobre un doble círculo son la inscripción \"PICKMAN S.A. / LA / CARTUJA / DE / SEVILLA\". En la parte inferior aparecen roleos y rosetas y la leyenda \"RECUERDO\".Está localizado sin fecha en planchas de estampación. Actualmente no se conoce su reproducción en piezas de loza.", "image": "stamp-78.webp", "decade": 1930}, {"id": 79, "period": "Década 1950", "desc": "El sello representa una composición formada por la leyenda \"PICKMAN S.A. / FÁBRICA DE LOZA / EN LA CARTUJA DE SEVILLA\", rematada por un círculo con el ancla y la inscripción \"PICKMAN S.A. SEVILLA\" en su interior. Este modelo está localizado sin fecha en planchas de estampación. Posiblemente se utilizó para series limitadas. Por el momento no se conoce su reproducción en piezas de loza.", "image": "stamp-79.webp", "decade": 1950}, {"id": 50, "period": "De 1965 a 1967", "desc": "Sello formado por un ancla y la leyenda \" LA CARTUJA\", figurando en la parte central. Se atribuye su realización al artista Aníbal García Aristi, diseñador de La Cartuja en los años de 1965 a 1967. Posiblemente, no llegó nunca a comercializarse, pues actualmente no se conoce su reproducción en piezas de loza. El modelo está documentado en el departamento de serigrafía de la fábrica.", "image": "stamp-50.webp", "decade": 1960}, {"id": 51, "period": "De 1965 a 1967", "desc": "Sello formado por un ancla y la leyenda \"fabricó / PICKMAN S.A. / diseño decoró\". Al igual que el sello anterior se atribuye su realización al artista Aníbal García Aristi, diseñador de la Cartuja de los años 1965 a 1967. Posiblemente no llegó nunca a comercializarse, pues actualmente no se conoce su reproducción en piezas de loza. Este modelo está localizado en el departamento de serigrafía de la fábrica.", "image": "stamp-51.webp", "decade": 1960}, {"id": 52, "period": "De 1970 a 1980", "desc": "Sello formado por un círculo con un ancla y la inscripción \"LA CARTUJA DE SEVILLA/PICKMAN S.A.\" Fuera del círculo suele llevar otras inscripciones, referentes a la calidad del decorado, como es el caso de las leyendas \"Colores inalterables\", \" Made in Spain\", Admite lavavajillas\", \"Pintando a mano bajo barniz\", entre otras. Asimismo, puede figurar un número, referente al año de fabricación en este caso el 12. El modelo está localizado en el departamento de serigrafía. Actualmente se reproduce de forma similar.", "image": "stamp-52.webp", "decade": 1970}, {"id": 54, "period": "Décadas de 1970 y 1980", "desc": "El sello representa un pergamino con la inscripción \"Torre del Oro\" en su interior. Se utilizó para identificar lozas de inferior calidad o defectuosas. Está localizado en el departamento de serigrafía de la fábrica y actualmente no se reproduce.", "image": "stamp-54.webp", "decade": 1970}, {"id": 53, "period": "Décadas de 1980 y 1990", "desc": "El sello representa un círculo rodeado de roleos, figurando en su interior el ancla con la inscripción \" LA CARTUJA DE SEVILLA / 1841 / PICKMAN S.A.\" Fuera del círculo puede aparecer con la leyenda \" MADE IN SPAIN\" y un número referente al año de fabricación de la pieza, en este caso el 29. EL modelo ese utiliza actualmente para marcar piezas pequeñas de la vajilla modelo \"Imperio\".", "image": "stamp-53.webp", "decade": 1980}, {"id": 55, "period": "Décadas de 1980 y 1900", "desc": "El sello representa una nueva versión del antiguo modelo conmemorativo de Isabel II, signado con el Nº 15. Solo se cambiaron los detalles del texto del registro central por \"PICKMAN S.A. / FABRICA DE LOZA LA CARTUJA / SEVILLA\" y la medalla de la Sociedad Económica de Amigos del País en Alicante, sustituyéndose por la emblemática áncora y la fecha de la fundación 1841. La adaptación fue realizada por el pintor Rafael Bonos en la década de 1970. En algunos casos lleva una inscripción como \" COLORES INALTERABLES/MADE IN SPAIN\", haciendo alusión a la calidad de la loza y un número que representa el año de la fabricación, en este caso el \"19\". Actualmente se sigue utilizando en las vajillas modelo \"Imperio\" y en piezas de series limitadas.", "image": "stamp-55.webp", "decade": 1980}, {"id": 56, "period": "Décadas de 1980 y 1990", "desc": "El sello representa un círculo, figurando en su interior un semicírculo con el ancla y las leyendas \" LA CARTUJA DE SEVILLA / PICKMAN S.A.\" Puede presentarse con diversidad de medidas y con otras inscripciones alusivas a la técnica decorativa y propiedades de la loza como \"COLORES INALTERABLES\"/MADE IN SPAIN\". Asimismo en la parte inferior lleva generalmente un número que representa el año de la fabricación de la pieza, en este caso el 18. El modelo es similar al Nº 44, solamente cambia la distribución de la leyenda. Actualmente se utiliza en todo tipo de piezas.", "image": "stamp-56.webp", "decade": 1980}, {"id": 57, "period": "Décadad de 1980 y 1990", "desc": "Sello estampado formado por un cinturón con hebilla símbolo de la Orden de la Jarretera inglesa del siglo XIV, rematado por una corona real y flanqueado por dos columnas. En su interior lleva un león rampante junto a un ancla y la leyenda \" LA CARTUJA DE SEVILLA/ PICKMAN S.A.\". Asimismo, en la base lleva escrito \"Modelo original para serie limitada 1988\". Se utiliza para piezas artísticas de series limitadas.", "image": "stamp-57.webp", "decade": 1980}, {"id": 80, "period": "Décadas de 1980 y 1990", "desc": "El sello representa una composición donde aparece en la parte inferior la inscripción \"PICKMAN S.A. / LA CARTUJA / DE / SEVILLA/\", seguida de un óvalo con el ancla inscrita, rodeado de hojas de acanto y rematado por una corona real. Este modelo se utilizó con fines publicitarios en la decoración de ceniceros.", "image": "stamp-80.webp", "decade": 1980}];

  function boot() {
    var root = document.querySelector('[data-stamp-archive]');
    if (!root || !document.getElementById('stampTrack')) return;

    // Cada arranque estrena listeners; el anterior se aborta (editor de temas).
    if (controller) controller.abort();
    controller = new AbortController();
    var signal = controller.signal;

    // assets/ es plano en Shopify, así que el dataset guarda solo el nombre.
    var base = root.dataset.assetBase || '';
    var IMG = function (name) { return base + name; };
    var REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var L = {
      seal: root.dataset.labelSeal || 'Sello',
      decade: root.dataset.labelDecade || 'Ir a la década de',
      zoomIn: root.dataset.labelZoomIn || 'Ampliar',
      zoomOut: root.dataset.labelZoomOut || 'Reducir'
    };


const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
/* v99: por debajo de 700px el archivo deja de ser un scroll-theatre vertical y
   pasa a un carrusel horizontal nativo con centrado por scroll. */
const mobileArchive=()=>window.matchMedia('(max-width:700px)').matches;
const story=document.getElementById('archivo');
const viewport=document.getElementById('stampViewport');
const track=document.getElementById('stampTrack');
const eraMenu=document.getElementById('stampEraMenu');
const totalEl=document.getElementById('stampTotal');
const currentIndexEl=document.getElementById('stampCurrentIndex');
const currentEraEl=document.getElementById('stampCurrentEra');
const timelineCurrent=document.getElementById('timelineCurrent');
const timelineStart=document.getElementById('timelineStart');
const timelineEnd=document.getElementById('timelineEnd');
const progressTrack=document.getElementById('stampProgressTrack');
const progressFill=document.getElementById('stampProgressFill');
const progressThumb=document.getElementById('stampProgressThumb');
const timelineTicks=document.getElementById('stampTimelineTicks');
const captionPeriod=document.getElementById('stampCaptionPeriod');
const captionDesc=document.getElementById('stampCaptionDesc');
const drawer=document.getElementById('stampDrawer');
let metrics={storyTop:0,scrollDistance:1,cardW:230,pitch:235};
let raf=0,activeIndex=0,currentId=SEALS[0]?.id||1,dragging=false,dragMoved=false,dragStartX=0,dragStoryY=0;
let renderPos=0,targetPos=0,lastPaint=performance.now(),snapTimer=0,snapRaf=0,isAutoSnapping=false;
const pointer={x:0,y:0,active:false};

function decadeOf(s){return Number(s.decade)||1840}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));}
function displayPeriod(value=''){
  return String(value)
    .replace(/Décadad\b/g,'Décadas')
    .replace(/Décadas\s+1840\s*-\s*50/g,'Décadas de 1840 y 1850')
    .replace(/Décadas de 1980 y 1900/g,'Décadas de 1980 y 1990')
    .replace(/,(?=\S)/g,', ')
    .replace(/(\d{4})y(?=\d{4})/g,'$1 y ')
    .replace(/(\d{4})y\s+(?=\d{4})/g,'$1 y ')
    .replace(/,\s+y\s+/g,' y ')
    .replace(/\s{2,}/g,' ')
    .trim();
}

function buildArchive(){
  if(!track)return;
  track.innerHTML=SEALS.map((s,i)=>`<article class="stamp-item" data-id="${s.id}" data-index="${i}" data-decade="${decadeOf(s)}" tabindex="0" role="button" aria-label="${escapeHtml(L.seal)} ${String(s.id).padStart(2,'0')}, ${escapeHtml(displayPeriod(s.period))}"><div class="stamp-seal-card"><img loading="lazy" draggable="false" src="${IMG(s.image)}" alt="${escapeHtml(L.seal)} ${String(s.id).padStart(2,'0')}"></div></article>`).join('');
  totalEl.textContent=String(SEALS.length).padStart(2,'0');
  const decades=[...new Set(SEALS.map(s=>decadeOf(s)))].sort((a,b)=>a-b);
  eraMenu.innerHTML=decades.map((d,i)=>`<button type="button" data-decade="${d}" class="${i===0?'active':''}" aria-label="${escapeHtml(L.decade)} ${d}">${d}</button>`).join('');
  timelineTicks.innerHTML=decades.map(d=>`<i class="stamp-timeline-tick" data-decade="${d}"></i>`).join('');
  timelineStart.textContent=decades[0]||1840; timelineEnd.textContent=decades[decades.length-1]||1990;
  track.querySelectorAll('.stamp-item').forEach(item=>{
    item.addEventListener('click',e=>{if(dragMoved){e.preventDefault();return;}openSeal(Number(item.dataset.id));});
    item.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openSeal(Number(item.dataset.id));}});
  });
  eraMenu.querySelectorAll('button').forEach(btn=>btn.addEventListener('click',()=>scrollToDecade(Number(btn.dataset.decade))));
  measure();
}

function measure(){
  if(!story||!viewport||!track||!track.children.length)return;
  const first=track.children[0];
  const cardW=first.getBoundingClientRect().width||230;
  const pitch=cardW*1.05;
  if(mobileArchive()){
    const maxScroll=Math.max(1,viewport.scrollWidth-viewport.clientWidth);
    metrics={storyTop:story.offsetTop,scrollDistance:maxScroll,cardW,pitch};
    story.style.height='auto';
    targetPos=localProgress()*Math.max(0,SEALS.length-1);
    renderPos=targetPos;
    placeTimelineTicks(); requestUpdate();
    return;
  }
  const perSeal=245;
  const scrollDistance=Math.max(window.innerHeight,(SEALS.length-1)*perSeal);
  metrics={storyTop:story.offsetTop,scrollDistance,cardW,pitch};
  story.style.height=`${window.innerHeight+scrollDistance}px`;
  targetPos=localProgress()*Math.max(0,SEALS.length-1);
  if(!Number.isFinite(renderPos))renderPos=targetPos;
  placeTimelineTicks(); requestUpdate();
}
function localProgress(){
  if(mobileArchive()){
    const max=Math.max(1,viewport.scrollWidth-viewport.clientWidth);
    return clamp(viewport.scrollLeft/max,0,1);
  }
  return clamp((window.scrollY-metrics.storyTop)/metrics.scrollDistance,0,1)
}
function scrollYForIndex(index){const denom=Math.max(1,SEALS.length-1);return metrics.storyTop+(clamp(index,0,SEALS.length-1)/denom)*metrics.scrollDistance}
function scrollToIndex(index,behavior='smooth'){
  index=clamp(index,0,SEALS.length-1);
  if(mobileArchive()){
    const item=track.children[index];
    if(!item)return;
    const left=item.offsetLeft-(viewport.clientWidth-item.offsetWidth)/2;
    viewport.scrollTo({left,behavior:behavior==='instant'?'auto':'smooth'});
    activeIndex=index;
    setActive(index,index/Math.max(1,SEALS.length-1));
    return;
  }
  const y=scrollYForIndex(index);
  if(behavior==='instant'){cancelSnapAnimation();window.scrollTo(0,y);return;}
  animateScrollTo(y,560);
}
function scrollToDecade(decade){let index=SEALS.findIndex(s=>decadeOf(s)===decade);if(index<0)index=SEALS.findIndex(s=>decadeOf(s)>=decade);if(index<0)index=SEALS.length-1;scrollToIndex(index)}
function placeTimelineTicks(){
  const denom=Math.max(1,SEALS.length-1);
  timelineTicks.querySelectorAll('.stamp-timeline-tick').forEach(tick=>{const d=Number(tick.dataset.decade);let i=SEALS.findIndex(s=>decadeOf(s)===d);if(i<0)i=SEALS.length-1;tick.style.left=`${(i/denom)*100}%`;});
}
function easeSmoother(t){return t*t*t*(t*(t*6-15)+10)}
function cancelSnapAnimation(){if(snapRaf){cancelAnimationFrame(snapRaf);snapRaf=0;}isAutoSnapping=false;}
function animateScrollTo(y,duration=540){
  cancelSnapAnimation();
  const from=window.scrollY,delta=y-from;
  if(Math.abs(delta)<1)return;
  if(REDUCED){window.scrollTo(0,y);requestUpdate();return;}
  const start=performance.now();isAutoSnapping=true;
  const step=now=>{
    const t=clamp((now-start)/duration,0,1);
    window.scrollTo(0,from+delta*easeSmoother(t));
    if(t<1){snapRaf=requestAnimationFrame(step);}else{snapRaf=0;isAutoSnapping=false;requestUpdate();}
  };
  snapRaf=requestAnimationFrame(step);
}
function scheduleSnap(){
  clearTimeout(snapTimer);
  if(mobileArchive())return;
  if(REDUCED)return;
  if(dragging||isAutoSnapping||drawer?.classList.contains('open'))return;
  const y=window.scrollY;
  const start=metrics.storyTop,end=metrics.storyTop+metrics.scrollDistance;
  if(y<=start+2||y>=end-2)return;
  snapTimer=setTimeout(()=>{
    if(dragging||isAutoSnapping)return;
    const raw=localProgress()*Math.max(0,SEALS.length-1);
    const nearest=Math.round(raw);
    animateScrollTo(scrollYForIndex(nearest),500);
  },145);
}
function paint(now=performance.now()){
  raf=0;if(!track)return;
  const progress=localProgress();
  if(mobileArchive()){
    const viewportCenter=viewport.scrollLeft+viewport.clientWidth/2;
    let nearest=0,nearestDist=Infinity;
    [...track.children].forEach((item,index)=>{
      item.style.transform='';item.style.opacity='1';item.style.zIndex='1';
      const center=item.offsetLeft+item.offsetWidth/2;
      const distance=Math.abs(center-viewportCenter);
      if(distance<nearestDist){nearestDist=distance;nearest=index;}
    });
    [...track.children].forEach((item,index)=>{
      item.classList.toggle('is-active',index===nearest);
      item.setAttribute('aria-current',index===nearest?'true':'false');
    });
    setActive(nearest,nearest/Math.max(1,SEALS.length-1));
    return;
  }
  targetPos=progress*Math.max(0,SEALS.length-1);
  const dt=Math.min(34,Math.max(8,now-lastPaint));lastPaint=now;
  const follow=REDUCED?1:1-Math.pow(.86,dt/16.67);
  renderPos+= (targetPos-renderPos)*follow;
  if(Math.abs(targetPos-renderPos)<.0008)renderPos=targetPos;
  const pos=renderPos;
  const cardW=metrics.cardW,pitch=metrics.pitch;
  const rotate=43,depth=.58,falloff=.58,fade=.10;
  let nearest=0,nearestDist=Infinity;
  [...track.children].forEach((item,index)=>{
    const offset=index-pos,distance=Math.abs(offset),ramp=Math.pow(distance,falloff);
    const tilt=Math.min(rotate*ramp,82)*Math.sign(offset);
    const mouseYaw=pointer.active?pointer.x*Math.sign(offset)*2.0:0;
    const mousePitch=pointer.active?pointer.y*.65:0;
    const translateX=offset*pitch,translateZ=-depth*cardW*ramp;
    const opacity=Math.max(.055,1-fade*distance),scale=1-Math.min(.07,distance*.011);
    item.style.transform=`translateX(calc(-50% + ${translateX.toFixed(2)}px)) translateZ(${translateZ.toFixed(2)}px) rotateY(${(-tilt+mouseYaw).toFixed(2)}deg) rotateX(${mousePitch.toFixed(2)}deg) scale(${scale.toFixed(3)})`;
    item.style.opacity=String(opacity);item.style.zIndex=String(200-Math.round(distance*10));
    item.classList.toggle('is-active',distance<.48);item.setAttribute('aria-current',distance<.48?'true':'false');
    if(distance<nearestDist){nearestDist=distance;nearest=index;}
  });
  setActive(nearest,progress);
  if(Math.abs(targetPos-renderPos)>.0008)requestUpdate();
}
function setActive(index,progress){
  if(index===undefined||!SEALS[index])return;activeIndex=index;
  const seal=SEALS[index],decade=decadeOf(seal),no=String(seal.id).padStart(2,'0');
  const periodLabel=displayPeriod(seal.period);
  currentIndexEl.textContent=no;currentEraEl.textContent=periodLabel;timelineCurrent.textContent=periodLabel;
  progressFill.style.width=`${progress*100}%`;progressThumb.style.left=`${progress*100}%`;
  captionPeriod.textContent=periodLabel;captionDesc.textContent=seal.desc;
  eraMenu.querySelectorAll('button').forEach(btn=>btn.classList.toggle('active',Number(btn.dataset.decade)===decade));
}
function requestUpdate(){if(!raf)raf=requestAnimationFrame(paint)}
window.addEventListener('scroll',()=>{requestUpdate();scheduleSnap();},{passive:true,signal});
window.addEventListener('wheel',()=>{clearTimeout(snapTimer);if(isAutoSnapping)cancelSnapAnimation();},{passive:true,signal});
window.addEventListener('touchstart',()=>{clearTimeout(snapTimer);if(isAutoSnapping)cancelSnapAnimation();},{passive:true,signal});
viewport?.addEventListener('scroll',()=>{if(mobileArchive())requestUpdate();},{passive:true});
viewport?.addEventListener('pointermove',e=>{
  if(mobileArchive())return;
  const r=viewport.getBoundingClientRect();pointer.x=clamp(((e.clientX-r.left)/r.width-.5)*2,-1,1);pointer.y=clamp(((e.clientY-r.top)/r.height-.5)*2,-1,1);pointer.active=true;if(!dragging)requestUpdate();
});
viewport?.addEventListener('pointerleave',()=>{pointer.active=false;requestUpdate();});
viewport?.addEventListener('pointerdown',e=>{if(mobileArchive()||e.pointerType==='touch')return;cancelSnapAnimation();clearTimeout(snapTimer);dragging=true;dragMoved=false;dragStartX=e.clientX;dragStoryY=window.scrollY;viewport.classList.add('is-dragging');viewport.setPointerCapture(e.pointerId);});
viewport?.addEventListener('pointermove',e=>{if(mobileArchive()||!dragging)return;const dx=e.clientX-dragStartX;if(Math.abs(dx)>5)dragMoved=true;const indexDelta=dx/metrics.pitch;const yPerIndex=metrics.scrollDistance/Math.max(1,SEALS.length-1);window.scrollTo(0,clamp(dragStoryY-indexDelta*yPerIndex,metrics.storyTop,metrics.storyTop+metrics.scrollDistance));});
function endDrag(){if(mobileArchive()||!dragging)return;dragging=false;viewport?.classList.remove('is-dragging');const nearest=Math.round(localProgress()*Math.max(0,SEALS.length-1));animateScrollTo(scrollYForIndex(nearest),460);setTimeout(()=>dragMoved=false,0)}
viewport?.addEventListener('pointerup',endDrag);viewport?.addEventListener('pointercancel',endDrag);
viewport?.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();scrollToIndex(activeIndex-1)}if(e.key==='ArrowRight'){e.preventDefault();scrollToIndex(activeIndex+1)}});
progressTrack?.addEventListener('click',e=>{const r=progressTrack.getBoundingClientRect();const ratio=clamp((e.clientX-r.left)/r.width,0,1);const idx=Math.round(ratio*Math.max(0,SEALS.length-1));scrollToIndex(idx)});

function openSeal(id){
  const s=SEALS.find(x=>x.id===id);if(!s)return;currentId=id;
  document.getElementById('drawerImage').src=IMG(s.image);
  document.getElementById('drawerNo').textContent=`${L.seal.toUpperCase()} ${String(s.id).padStart(2,'0')}`;
  document.getElementById('drawerTitle').textContent=`${L.seal} ${String(s.id).padStart(2,'0')}`;
  document.getElementById('drawerPeriod').textContent=displayPeriod(s.period);
  document.getElementById('drawerDesc').textContent=s.desc;
  setStampZoomState(false);
  const i=SEALS.findIndex(x=>x.id===id);document.getElementById('stampPrev').disabled=i<=0;document.getElementById('stampNext').disabled=i>=SEALS.length-1;
  drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');document.body.classList.add('stamp-modal-lock');
}
function closeDrawer(){drawer.classList.remove('open');setStampZoomState(false);drawer.setAttribute('aria-hidden','true');document.body.classList.remove('stamp-modal-lock')}
function moveSeal(dir){let i=SEALS.findIndex(x=>x.id===currentId);if(i<0)return;i=clamp(i+dir,0,SEALS.length-1);openSeal(SEALS[i].id)}
const zoomTrigger=document.getElementById('stampZoomTrigger');
const zoomHint=zoomTrigger?.querySelector('.stamp-zoom-hint');
function setStampZoomState(zoomed){
  drawer?.classList.toggle('image-zoomed',zoomed);
  zoomTrigger?.setAttribute('aria-expanded',zoomed?'true':'false');
  if(zoomHint)zoomHint.textContent=zoomed?L.zoomOut:L.zoomIn;
  zoomTrigger?.setAttribute('aria-label',zoomed?L.zoomOut:L.zoomIn);
}
function toggleStampZoom(){
  if(!drawer?.classList.contains('open'))return;
  setStampZoomState(!drawer.classList.contains('image-zoomed'));
}
zoomTrigger?.addEventListener('click',e=>{e.stopPropagation();toggleStampZoom();});
document.getElementById('stampClose').onclick=closeDrawer;document.getElementById('stampBackdrop').onclick=closeDrawer;document.getElementById('stampPrev').onclick=()=>moveSeal(-1);document.getElementById('stampNext').onclick=()=>moveSeal(1);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(drawer.classList.contains('open')){if(e.key==='ArrowLeft')moveSeal(-1);if(e.key==='ArrowRight')moveSeal(1);}},{signal});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(measure,140)},{signal});
buildArchive();requestAnimationFrame(()=>{measure();renderPos=targetPos;requestUpdate();});

  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
  document.addEventListener('shopify:section:load', boot);
})();
